// Application-metric instrumentation shared by every publish method: one
    // timer + one status-labelled counter per send. A failed send is counted
    // as an error and rethrown, never counted as a success.
    private static async Task MeasuredPublishAsync(string topic, string eventName, Func<Task> send)
    {
        var status = "success";
        var timer = MqMetrics.PublishDurationSeconds
            .WithLabels("ecommerce.ProductService", "mq", topic, eventName)
            .NewTimer();
        try
        {
            await send().ConfigureAwait(false);
        }
        catch
        {
            status = "error";
            throw;
        }
        finally
        {
            timer.Dispose();
            MqMetrics.PublishTotal
                .WithLabels("ecommerce.ProductService", "mq", topic, eventName, status)
                .Inc();
        }
    }

    public void Dispose()
    {
        _producer.Flush(TimeSpan.FromSeconds(5));
        _producer.Dispose();
    }
